<!-- 文件作用：在小程序内管理用户、服务、俱乐部、订单争议、游戏主题、公告和操作审计。 -->
<template><AppShell title="平台管理" back><view v-if="error" class="error-box mb">{{ error }}</view><EmptyState v-if="state.ready && state.user?.role!=='admin'" title="仅平台管理员可访问" detail="权限由服务端核验，请使用管理员账号登录" icon="shield"><button class="text-btn" @click="go('/pages/account/login')">切换账号</button></EmptyState><template v-else-if="state.user?.role==='admin'">
<view class="overview"><view v-for="metric in metrics" :key="metric.key" class="metric"><text class="metric-value">{{ metric.money?'¥'+money(overview[metric.key]):overview[metric.key]||0 }}</text><text class="metric-name">{{ metric.label }}</text></view></view><view class="admin-alert" v-if="overview.pending_services||overview.pending_clubs||overview.disputed_orders"><Icon name="bell" :size="18"/><text>{{ overview.pending_services||0 }} 个服务待审核 · {{ overview.pending_clubs||0 }} 个俱乐部申请 · {{ overview.disputed_orders||0 }} 个争议</text></view><scroll-view scroll-x class="admin-tabs"><view class="tabs"><button v-for="item in tabs" :key="item.id" :class="['tab',{active:tab===item.id}]" @click="selectTab(item.id)">{{ item.name }}</button></view></scroll-view>
<view class="admin-toolbar" v-if="tab!=='settings'"><input v-model="query" class="input" placeholder="搜索全部名称、用户或订单号" confirm-type="search" @confirm="loadData()"/><button class="text-btn refresh-btn" :disabled="loading" @click="loadData()"><Icon name="refresh" :size="18"/></button></view><view v-if="loading" class="loading-line">正在加载管理数据…</view>
<template v-else-if="tab==='users'"><view v-for="user in users" :key="user.id" class="admin-card"><view class="row between"><view class="row"><view class="avatar">{{ user.nickname?.slice(0,1) }}</view><view class="stack compact"><text class="item-title">{{ user.nickname }}</text><text class="hint">{{ user.role==='admin'?'平台管理员':user.provider_enabled?'玩家 / 打手':'玩家' }} · {{ user.id }}</text></view></view><text :class="user.status==='frozen'?'danger':'accent'" class="small">{{ user.status==='frozen'?'已冻结':'正常' }}</text></view><text class="muted">{{ user.bio||'暂未填写简介' }}</text><button v-if="user.id!==state.user.id" :class="['btn btn-small',user.status==='frozen'?'btn-secondary':'btn-danger']" :disabled="busy" @click="updateItem('users',user.id,{status:user.status==='frozen'?'active':'frozen'})">{{ user.status==='frozen'?'解除冻结':'冻结账户' }}</button></view></template>
<template v-else-if="tab==='services'"><view v-for="service in services" :key="service.id" class="admin-card"><view class="row between"><text class="item-title">{{ service.title }}</text><text class="pill">{{ statusLabel(service.status) }}</text></view><view class="service-summary"><image :src="assetUrl(service.cover_url)" mode="aspectFill"/><view class="stack compact"><text>{{ service.provider_name }} · {{ service.category }}</text><text class="accent">¥{{ money(service.price_cents) }}/{{ service.unit }}</text><text class="hint">{{ service.description }}</text></view></view><view class="admin-actions"><button v-if="service.status!=='active'" class="btn btn-small" :disabled="busy" @click="updateItem('services',service.id,{status:'active'})">审核通过</button><button v-if="service.status==='pending'" class="btn btn-secondary btn-small" :disabled="busy" @click="updateItem('services',service.id,{status:'rejected'})">不予通过</button><button v-if="service.status==='active'" class="btn btn-secondary btn-small" :disabled="busy" @click="updateItem('services',service.id,{status:'paused'})">下架服务</button><button class="text-btn" @click="go('/pages/services/detail?id='+service.id)">查看详情</button></view></view></template>
<template v-else-if="tab==='clubs'"><view v-for="club in clubs" :key="club.id" class="admin-card"><view class="row between"><text class="item-title">{{ club.name }}</text><text class="pill">{{ club.verified?'已认证':statusLabel(club.status) }}</text></view><text class="muted">负责人 {{ club.owner_name }} · {{ club.member_count||0 }} 位成员</text><text class="small">{{ club.description }}</text><view class="admin-actions"><button v-if="club.status!=='active'" class="btn btn-small" :disabled="busy" @click="updateItem('clubs',club.id,{status:'active',verified:true})">通过并认证</button><button v-if="club.status==='pending'" class="btn btn-secondary btn-small" :disabled="busy" @click="updateItem('clubs',club.id,{status:'rejected',verified:false})">拒绝申请</button><button v-if="club.status==='active'" class="btn btn-secondary btn-small" :disabled="busy" @click="updateItem('clubs',club.id,{status:'active',verified:!club.verified})">{{ club.verified?'取消认证':'授予认证' }}</button><button class="text-btn" @click="go('/pages/community/clubs/detail?id='+club.id)">成员 / 订单</button></view></view></template>
<template v-else-if="tab==='orders'"><view class="tabs mb"><button :class="['tab',{active:!disputesOnly}]" @click="disputesOnly=false;loadData()">全部订单</button><button :class="['tab',{active:disputesOnly}]" @click="disputesOnly=true;loadData()">退款与争议</button></view><view v-for="order in displayedOrders" :key="order.id" class="admin-card" @click="go('/pages/orders/detail?id='+order.id)"><view class="row between"><text class="item-title">{{ order.title }}</text><text class="accent nowrap">¥{{ money(order.amount_cents) }}</text></view><text class="hint">{{ order.order_no }}</text><text class="small">{{ order.buyer_name }} → {{ order.provider_name||'未接单' }}</text><view class="row between"><text class="pill">{{ statusLabel(order.status) }}</text><text v-if="order.refund_status && order.refund_status!=='none'" class="refund-tag">{{ refundName(order.refund_status) }}</text></view><text class="text-btn">查看证据与处理争议</text></view></template>
<template v-else-if="tab==='games'"><view class="row between mb"><text class="hint">颜色、封面、分类会同步到客户端</text><button class="text-btn" @click="editGame()"><Icon name="plus" :size="15"/>新增游戏</button></view><view v-for="game in games" :key="game.id" class="admin-card"><view class="game-admin-heading"><image :src="assetUrl(game.cover_url)" mode="aspectFill"/><view><text class="item-title">{{ game.name }}</text><view class="game-colors"><text v-for="key in colorKeys" :key="key.id" :style="{background:game[key.id]}"/></view><text class="hint">{{ (game.categories||[]).join(' / ') }}</text></view></view><view class="row between"><text class="pill">{{ game.enabled?'已启用':'已隐藏' }}</text><button class="btn btn-secondary btn-small" @click="editGame(game)">编辑主题与封面</button></view></view></template>
<template v-else-if="tab==='audit'"><view v-for="(entry,index) in audits" :key="entry.id||index" class="audit-entry"><view class="row between"><text class="item-title">{{ entry.action }}</text><text class="hint">{{ time(entry.created_at) }}</text></view><text class="muted">{{ entry.actor_id }} · {{ entry.target_id }}</text><text v-if="entry.note" class="hint audit-detail">{{ stringify(entry.note) }}</text></view></template>
<view v-else-if="tab==='settings'" class="form-section"><view class="field"><text class="field-label">平台名称</text><input v-model="settings.site_name" class="input" maxlength="20"/></view><view class="field"><text class="field-label">首页公告</text><textarea v-model="settings.announcement" class="input" maxlength="300"/></view><button class="btn" :disabled="busy" @click="saveSettings">保存平台设置</button><button class="text-btn block" @click="go('/pages/manage/settings')">协议版本与微信支付配置</button><text class="hint block">协议支持发布独立版本，支付秘密由服务端加密保存，不在客户端持久缓存。</text></view>
<button v-if="hasMore && !loading" class="text-btn load-more" @click="loadData(true)">加载更多记录</button><EmptyState v-if="!loading && tab!=='settings' && !filtered.length" title="没有匹配的数据" detail="可以更换关键词或稍后刷新" icon="search"/>
</template>
<view v-if="editing" class="modal-mask" @click="editing=false"><scroll-view scroll-y class="game-modal panel form-section" @click.stop><view class="row between mb"><text class="section-title">{{ newGame?'添加游戏':'编辑游戏主题' }}</text><button class="text-btn" @click="editing=false">关闭</button></view><view class="field" v-if="newGame"><text class="field-label">游戏标识（小写英文）</text><input v-model="gameForm.id" class="input" placeholder="例如 league" maxlength="30"/></view><view class="two-fields"><view class="field"><text class="field-label">游戏名称</text><input v-model="gameForm.name" class="input" maxlength="30"/></view><view class="field"><text class="field-label">简称</text><input v-model="gameForm.short_name" class="input" maxlength="8"/></view></view><view class="field"><text class="field-label">主题标语</text><input v-model="gameForm.subtitle" class="input" maxlength="80"/></view><view class="two-fields"><view class="field" v-for="key in colorKeys" :key="key.id"><text class="field-label">{{ key.name }}</text><view class="color-input"><text :style="{background:gameForm[key.id]}"/><input v-model="gameForm[key.id]" maxlength="7" placeholder="#00e18a"/></view></view></view><view class="field"><text class="field-label">服务分类（逗号分隔）</text><input v-model="gameForm.categoriesText" class="input" placeholder="陪练教学,组队陪玩,任务协作"/></view><view class="field"><text class="field-label">游戏图标</text><view class="row upload-actions"><image v-if="gameForm.icon_url" class="game-icon-preview" :src="assetUrl(gameForm.icon_url)" mode="aspectFill"/><button class="btn btn-small btn-secondary" :disabled="busy" @click="uploadCover('icon')">上传独立图标</button><button class="text-btn" @click="gameForm.icon_url=gameForm.covers[0]||''">使用首张封面</button></view><text class="hint">建议使用清晰方形图标，和游戏封面分开设置。</text></view><view class="row between mb"><text class="field-label">封面素材库</text><button class="text-btn" :disabled="busy" @click="uploadCover('cover')">上传封面</button></view><view class="cover-library"><view v-for="cover in coverLibrary" :key="cover" :class="['library-cover',{selected:gameForm.covers.includes(cover)}]" @click="toggleCover(cover)"><image :src="assetUrl(cover)" mode="aspectFill"/><view v-if="gameForm.covers.includes(cover)" class="library-number">{{ gameForm.covers.indexOf(cover)+1 }}</view></view></view><text class="hint block">按选择顺序排列，第一张作为游戏主封面，至少选择一张。</text><view class="two-fields"><view class="field"><text class="field-label">排序（越小越靠前）</text><input v-model="gameForm.sort_order" type="number" class="input"/></view><view class="field"><text class="field-label">游戏状态</text><NativeSwitch :checked="gameForm.enabled" color="#00e18a" @change="changeGameEnabled"/><text class="hint">{{ gameForm.enabled?'对玩家可见':'暂时隐藏' }}</text></view></view><button class="btn" :disabled="busy" @click="saveGame">{{ busy?'保存中…':'保存游戏配置' }}</button><view class="modal-bottom"/></scroll-view></view>
</AppShell></template>
<script setup lang="ts">
import { chooseUploadImage } from '../../lib/media'
import { ref, reactive, computed, watch } from 'vue'
import { onShow, onHide, onUnload } from '@dcloudio/uni-app'
import AppShell from '../../components/AppShell.vue'
import NativeSwitch from '../../components/NativeSwitch.vue'
import EmptyState from '../../components/EmptyState.vue'
import Icon from '../../components/Icon.vue'
import { state, init, sessionRevision } from '../../lib/store'
import { getAdminOverview, listAdminResource, moderateResource, createGame, updateGame, updateSettings, getAdminSettings } from '../../api/admin.api'
import type { ModerationResource } from '../../api/admin.api'
import type { Game, User, Service, Club, Order, Audit } from '../../types/models'
import { token, errorMessage, isCancelled } from '../../api/client'
import { go, notify, money, time, statusLabel, assetUrl } from '../../lib/format'

/** 后台资源页签及表单支持的颜色字段。 */
type AdminTab = 'services' | 'clubs' | 'orders' | 'users' | 'games' | 'audit' | 'settings'
type GameColorKey = 'primary_color' | 'bg_color' | 'surface_color' | 'text_color'
type GameDraft = Omit<Game,'sort_order'> & { categoriesText: string; sort_order: string | number }
/** 创建独立游戏草稿，避免取消编辑时改变全局主题。 */
function emptyGame(): GameDraft {
  return { id:'', name:'', short_name:'', subtitle:'', primary_color:'#00e18a', bg_color:'#0a1110', surface_color:'#15201e', text_color:'#f2f5f3', cover_url:'', covers:[], icon_url:'', enabled:true, sort_order:state.games.length+1, categories:[], categoriesText:'' }
}
const hasMore=ref(false),overview=ref<Record<string,number>>({}),tab=ref<AdminTab>('services'),query=ref(''),loading=ref(false),busy=ref(false),error=ref(''),disputesOnly=ref(false),editing=ref(false),newGame=ref(false)
const users=ref<User[]>([]),services=ref<Service[]>([]),clubs=ref<Club[]>([]),orders=ref<Order[]>([]),games=ref<Game[]>([]),audits=ref<Audit[]>([])
const settings=reactive({site_name:'',announcement:''}),gameForm=reactive<GameDraft>(emptyGame()),uploadedCovers=ref<string[]>([])
const tabs: {id: AdminTab;name:string}[]=[{id:'services',name:'服务审核'},{id:'clubs',name:'俱乐部'},{id:'orders',name:'订单与售后'},{id:'users',name:'用户'},{id:'games',name:'游戏配置'},{id:'audit',name:'操作记录'},{id:'settings',name:'平台设置'}]
const metrics=[{key:'users',label:'注册用户'},{key:'orders',label:'全部订单'},{key:'services',label:'服务数量'},{key:'revenue_cents',label:'完成交易额',money:true}]
const colorKeys: {id:GameColorKey;name:string}[]=[{id:'primary_color',name:'主题强调色'},{id:'bg_color',name:'页面背景色'},{id:'surface_color',name:'卡片背景色'},{id:'text_color',name:'正文颜色'}]
const filtered=computed(()=>({users:users.value,services:services.value,clubs:clubs.value,orders:orders.value,games:games.value,audit:audits.value,settings:[]}[tab.value]))
const displayedOrders=computed(()=>orders.value.filter(order=>!disputesOnly.value||(order.refund_status&&order.refund_status!=='none')||order.status==='disputed'))
const coverLibrary=computed(()=>[...new Set([...state.games.flatMap(item=>item.covers||[]),...gameForm.covers,...uploadedCovers.value])])
let loadVersion=0,visible=true,choosingImage=false
/** 捕获后台请求所属管理员，账号变化后不能沿用原管理响应。 */
function currentSession(){return{id:state.user?.id,token:token(),revision:sessionRevision()}}
/** 仅在相同管理员会话且页面可见时接受后台数据。 */
function sameSession(session: ReturnType<typeof currentSession>,requireVisible=true): boolean {return (!requireVisible||visible)&&state.user?.role==='admin'&&session.id===state.user.id&&session.token===token()&&session.revision===sessionRevision()}
/** 离开或切换身份时作废迟到请求并移除管理数据和编辑草稿。 */
function hidePage(): void {visible=false;loadVersion++;loading.value=false;if(choosingImage&&state.user?.role==='admin')return;users.value=[];services.value=[];clubs.value=[];orders.value=[];games.value=[];audits.value=[];overview.value={};editing.value=false;Object.assign(gameForm,emptyGame());uploadedCovers.value=[]}
watch(()=>state.user?.id,()=>{if(state.user?.role!=='admin')hidePage()})
/** 验证管理身份后加载摘要和当前资源页签。 */
async function load(): Promise<void> {visible=true;if(choosingImage)return;let session: ReturnType<typeof currentSession> | undefined;try{await init(true);if(!visible||state.user?.role!=='admin')return;session=currentSession();const result=await getAdminOverview();if(!sameSession(session))return;overview.value=result;await loadData()}catch(err){if(visible&&(!session||sameSession(session)))error.value=errorMessage(err)}}
/** 使用具名资源接口分页查询，拒绝前一个页签的迟到数据。 */
async function loadData(append=false): Promise<void> {
  if(!visible||state.user?.role!=='admin')return
  const version=++loadVersion,currentTab=tab.value,session=currentSession()
  loading.value=true;error.value=''
  const params={limit:100,offset:append?filtered.value.length:0,q:query.value.trim(),...(currentTab==='orders'&&disputesOnly.value?{refund:1}:{})}
  try {
    if(currentTab==='settings'){const result=await getAdminSettings();if(version!==loadVersion||!sameSession(session))return;Object.assign(settings,result);hasMore.value=false;return}
    const result=await listAdminResource(currentTab,params)
    if(version!==loadVersion||!sameSession(session))return
    switch(currentTab){
      case 'users': users.value=append?[...users.value,...result as User[]]:result as User[];break
      case 'services': services.value=append?[...services.value,...result as Service[]]:result as Service[];break
      case 'clubs': clubs.value=append?[...clubs.value,...result as Club[]]:result as Club[];break
      case 'orders': orders.value=append?[...orders.value,...result as Order[]]:result as Order[];break
      case 'games': games.value=append?[...games.value,...result as Game[]]:result as Game[];break
      case 'audit': audits.value=append?[...audits.value,...result as Audit[]]:result as Audit[];break
    }
    hasMore.value=result.length===100
  }catch(err){if(version===loadVersion&&sameSession(session))error.value=errorMessage(err)}finally{if(version===loadVersion)loading.value=false}
}
/** 切换资源分类，保留其他分类的类型但清空当前搜索。 */
function selectTab(value: AdminTab): void {tab.value=value;query.value='';loadData()}
/** 审核用户、服务和俱乐部后同步刷新统计。 */
async function updateItem(type: ModerationResource,id: string,body:{status?:string;verified?:boolean}): Promise<void> {if(busy.value||state.user?.role!=='admin')return;const session=currentSession();busy.value=true;try{await moderateResource(type,id,body);if(!sameSession(session))return;await loadData();if(!sameSession(session))return;const result=await getAdminOverview();if(!sameSession(session))return;overview.value=result;notify('处理结果已保存')}catch(err){if(sameSession(session))notify(err)}finally{busy.value=false}}
/** 显示资金售后的准确状态。 */
function refundName(value: string): string {return({requested:'等待卖方处理',rejected:'卖方已拒绝',escalated:'申请平台介入',approved:'退款完成',processing:'退款通道处理中'} as Record<string,string>)[value]||value}
/** 把审计内容转为安全的纯文本。 */
function stringify(value: unknown): string {return typeof value==='string'?value:JSON.stringify(value)}
/** 建立新游戏或已有游戏的独立编辑快照。 */
function editGame(game?: Game): void {newGame.value=!game;Object.assign(gameForm,emptyGame(),game?JSON.parse(JSON.stringify(game)):{});gameForm.categoriesText=(gameForm.categories.length?gameForm.categories:['陪练教学','组队陪玩','任务协作']).join(',');editing.value=true}
/** 控制封面顺序，第一张为默认封面。 */
function toggleCover(url: string): void {const index=gameForm.covers.indexOf(url);if(index>=0)gameForm.covers.splice(index,1);else gameForm.covers.push(url)}
/** 使用官方裁剪压缩流程上传后台游戏图标或封面。 */
async function uploadCover(kind='cover'): Promise<void> {if(busy.value||state.user?.role!=='admin')return;const session=currentSession();busy.value=true;choosingImage=true;try{const url=await chooseUploadImage(kind==='icon'?'game_icon':'game_cover');if(!sameSession(session,false))return;if(kind==='icon')gameForm.icon_url=url;else{uploadedCovers.value.push(url);gameForm.covers.push(url)}notify('图片已处理并上传')}catch(err){if(sameSession(session,false)&&!isCancelled(err))notify(err)}finally{busy.value=false;choosingImage=false}}
/** 验证主题颜色、分类和封面，并通过游戏域 API 保存。 */
async function saveGame(): Promise<void> {if(busy.value||state.user?.role!=='admin')return;const session=currentSession();if(!/^[a-z][a-z0-9-]{1,29}$/.test(gameForm.id)||!gameForm.name.trim()||!gameForm.short_name.trim())return notify('请填写有效游戏标识、名称和简称');if(colorKeys.some(key=>!/^#[0-9a-f]{6}$/i.test(gameForm[key.id])))return notify('颜色请使用六位十六进制值');if(!gameForm.covers.length)return notify('至少选择一张游戏封面');const categories=gameForm.categoriesText.split(/[,，]/).map(item=>item.trim()).filter(Boolean);if(!categories.length)return notify('至少填写一种服务分类');busy.value=true;try{const{categoriesText,...draft}=gameForm;const body: Game={...draft,sort_order:Number(gameForm.sort_order)||0,categories,cover_url:gameForm.covers[0]||''};if(newGame.value)await createGame(body);else await updateGame(gameForm.id,body);if(!sameSession(session))return;editing.value=false;await init(true);if(!sameSession(session))return;await loadData();if(sameSession(session))notify('游戏主题已更新')}catch(err){if(sameSession(session))notify(err)}finally{busy.value=false}}
/** 保存平台名称和首页公告。 */
async function saveSettings(): Promise<void> {if(busy.value||state.user?.role!=='admin')return;const session=currentSession();if(!settings.site_name.trim())return notify('请填写平台名称');busy.value=true;try{await updateSettings(settings);if(!sameSession(session))return;await init(true);if(sameSession(session))notify('平台设置已保存')}catch(err){if(sameSession(session))notify(err)}finally{busy.value=false}}
/** 接收官方 switch 的布尔事件，不让DOM Event混入业务表单。 */
function changeGameEnabled(event: {detail:{value:boolean}}): void {gameForm.enabled=event.detail.value}
onShow(load)
onHide(hidePage)
onUnload(()=>{choosingImage=false;hidePage()})
</script>
